"""Energy ledger and per-configuration breakdown (audit round): every
component of the CIM request energy with its formula, unit energy, source,
coverage, static/dynamic status and the double-counting check; the static
items the models define (none: Accelergy leakage 0, fabric idle_power_w
None) and the added always-on link bound for the GRS tier; the uncovered
items.

    python3 gpu_comparison/scripts/energy_audit.py -> gpu_comparison/energy_ledger.csv, energy_breakdown.csv
"""
import csv
import os

G = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
